import unittest
from query import parse_query_multimap

class TestParseQueryMultimap(unittest.TestCase):
    def test_parse_query_multimap_basic(self):
        result = parse_query_multimap("foo=bar&baz=qux")
        self.assertEqual(result, {"foo": ["bar"], "baz": ["qux"]})

    def test_parse_query_multimap_duplicate_keys(self):
        result = parse_query_multimap("a=1&a=2&a=3")
        self.assertEqual(result, {"a": ["1", "2", "3"]})

    def test_parse_query_multimap_blank_values(self):
        result = parse_query_multimap("foo=&bar=baz")
        self.assertEqual(result, {"foo": [""], "bar": ["baz"]})

    def test_parse_query_multimap_plus_as_space(self):
        result = parse_query_multimap("foo=bar+baz")
        self.assertEqual(result, {"foo": ["bar baz"]})

    def test_parse_query_multimap_leading_question_mark(self):
        result = parse_query_multimap("?foo=bar")
        self.assertEqual(result, {"foo": ["bar"]})

    def test_parse_query_multimap_empty(self):
        self.assertEqual(parse_query_multimap(""), {})
        self.assertEqual(parse_query_multimap("?"), {})

if __name__ == "__main__":
    unittest.main()

