def validate_port(value):
    """Return a valid TCP/UDP port unchanged.

    A valid value is an actual integer from 1 through 65535 inclusive.
    Strings, floats, booleans, and other types must raise TypeError;
    out-of-range integers must raise ValueError.
    """
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError("Port must be an integer")
    if value < 1 or value > 65535:
        raise ValueError("Port must be between 1 and 65535")
    return value

